begin;
create extension if not exists pgcrypto;
create table if not exists public.cases(case_id uuid primary key default gen_random_uuid(),customer_id text not null,case_type text not null,title text,description text,status text not null,priority text not null,assigned_to text,fraud_alert_id text,assessment_id text,transaction_id text,account_id text,resolution text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz,closed_at timestamptz,metadata jsonb not null default '{}'::jsonb,idempotency_key text);
create unique index if not exists cases_fraud_alert_unique on public.cases(fraud_alert_id) where fraud_alert_id is not null;
create unique index if not exists cases_idempotency_unique on public.cases(idempotency_key) where idempotency_key is not null;
create index if not exists cases_customer_idx on public.cases(customer_id); create index if not exists cases_status_idx on public.cases(status); create index if not exists cases_priority_idx on public.cases(priority); create index if not exists cases_assigned_idx on public.cases(assigned_to); create index if not exists cases_transaction_idx on public.cases(transaction_id); create index if not exists cases_created_idx on public.cases(created_at desc);
create table if not exists public.case_notes(note_id uuid primary key default gen_random_uuid(),case_id uuid not null references public.cases(case_id) on delete cascade,author_type text not null,author_id text,note_type text not null,content text not null,created_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb); create index if not exists notes_case_created_idx on public.case_notes(case_id,created_at);
create table if not exists public.approvals(approval_id uuid primary key default gen_random_uuid(),case_id uuid not null references public.cases(case_id),action_type text not null,action_payload jsonb not null,status text not null,requested_by text not null,requested_at timestamptz not null default now(),reviewed_by text,reviewed_at timestamptz,review_note text,expires_at timestamptz,idempotency_key text,executed_at timestamptz); create unique index if not exists approval_idempotency_unique on public.approvals(idempotency_key) where idempotency_key is not null; create unique index if not exists approval_pending_unique on public.approvals(case_id,action_type) where status='PENDING'; create index if not exists approvals_case_idx on public.approvals(case_id); create index if not exists approvals_status_idx on public.approvals(status); create index if not exists approvals_action_type_idx on public.approvals(action_type);
create table if not exists public.card_states(card_id text primary key,customer_id text not null,account_id text,status text not null,previous_status text,updated_at timestamptz not null default now(),updated_by text not null,last_case_id uuid references public.cases(case_id),metadata jsonb not null default '{"synthetic":true,"source":"demo_bank_control"}'::jsonb);
create table if not exists public.notifications(notification_id uuid primary key default gen_random_uuid(),case_id uuid not null references public.cases(case_id),customer_id text not null,channel text not null,destination_masked text,subject text,content text not null,status text not null,provider text not null,created_at timestamptz not null default now(),sent_at timestamptz,failure_reason text,metadata jsonb not null default '{}'::jsonb,idempotency_key text); create unique index if not exists notification_idempotency_unique on public.notifications(idempotency_key) where idempotency_key is not null; create index if not exists notifications_case_idx on public.notifications(case_id); create index if not exists notifications_customer_idx on public.notifications(customer_id); create index if not exists notifications_status_idx on public.notifications(status);
create table if not exists public.audit_events(audit_id uuid primary key default gen_random_uuid(),case_id uuid references public.cases(case_id),customer_id text,actor_type text not null,actor_id text,event_type text not null,entity_type text not null,entity_id text not null,action text not null,before_state jsonb,after_state jsonb,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now()); create index if not exists audit_case_created_idx on public.audit_events(case_id,created_at); create index if not exists audit_customer_created_idx on public.audit_events(customer_id,created_at);
alter table public.cases enable row level security; alter table public.case_notes enable row level security; alter table public.approvals enable row level security; alter table public.card_states enable row level security; alter table public.notifications enable row level security; alter table public.audit_events enable row level security;
revoke all on public.cases,public.case_notes,public.approvals,public.card_states,public.notifications,public.audit_events from anon,authenticated;
commit;
notify pgrst, 'reload schema';
